M = [
{"id":"sosyalmedya","yol":Y,"baslik":"Sosyal medyada paylaşım ve gıybet","ar":"وسائل التواصل الاجتماعي",
 "hanefi":"Sosyal medyada yazılan ve paylaşılan her söz, söylenmiş söz hükmündedir. Gıybet, iftira, alay, kötü lakap, müstehcen içerik ve doğruluğu araştırılmamış haberleri yaymak sosyal medyada da haramdır; paylaşımın çok kişiye ulaşması günahı ağırlaştırır. Başkasının fotoğrafını ve özel bilgilerini izni olmadan paylaşmak kul hakkıdır. Faydalı bilgi, güzel söz ve iyiliği yaymak ise sadaka sevabı kazandırır.",
 "mez":{"maliki":["Aynı","Söz ve yazının hükmü aynıdır."],
        "safii":["Aynı","Gıybetin yazıyla yapılması da gıybettir."],
        "hanbeli":["Aynı","Kul hakkı helalleşmeyi gerektirir."]},
 "sebep":"Mezheplerde ittifak vardır; yazı (kitâbet) söz hükmündedir.",
 "delil":[["ayet","Hucurât 49:6","./#49-6","“Ey iman edenler! Bir fasık size bir haber getirirse onu iyice araştırın…”"],
          ["ayet","Hucurât 49:12","./#49-12","“…Birbirinizin gıybetini yapmayın.”"],
          ["hadis","“Kişiye yalan olarak duyduğu her şeyi anlatması yeter.”",hadis("كفى بالمرء كذبا أن يحدث بكل ما سمع"),"Müslim, Mukaddime, 5."]],
 "usul":"“Yazı, söz gibidir” (el-kitâbu ke’l-hitâb) kaidesi; sonucu yaygınlaşan kötülükte günahın da yaygınlaşması."},
{"id":"oyun","yol":Y,"baslik":"Bilgisayar ve telefon oyunları","ar":"الألعاب الإلكترونية",
 "hanefi":"Eğlence ve dinlenme amacıyla oynanan oyunlar, içinde haram unsur bulunmadıkça caizdir. Kumar, bahis ve para yatırarak şansa dayalı ödül (loot box) içeren, şiddeti ve müstehcenliği özendiren, şirk ve dinî değerlerle alay unsurları barındıran oyunlar caiz değildir. Namazı geciktiren, ders ve görevleri ihmal ettiren, bağımlılık yapacak ölçüde oynanan oyunlar da sakıncalıdır. Anne-baba çocuklarının oyun süresini ve içeriğini denetlemelidir.",
 "mez":{"maliki":["Şartlı caiz","Satranç gibi oyunlarda klasik âlimler ihtilaf etmiştir."],
        "safii":["Şartlı caiz","Kumarsız satrancı caiz görmüşlerdir."],
        "hanbeli":["Şartlı caiz","Tavla gibi şansa dayalı oyunlar haram görülmüştür."]},
 "sebep":"Oyunun kendisinin mi yoksa içerdiği unsurların ve sonuçlarının mı hükmü belirlediği.",
 "delil":[["hadis","“Tavla oynayan Allah’a ve Resulüne isyan etmiştir.”",hadis("من لعب بالنرد فقد عصى الله ورسوله"),"Ebû Dâvûd, Edeb, 56; Muvatta’, Rü’yâ, 6."],
          ["ayet","Cuma 62:11","./#62-11","“Bir ticaret veya eğlence gördüklerinde ona yöneldiler ve seni ayakta bıraktılar…”"]],
 "usul":"Eşyada aslolan mubahlıktır; hüküm, kumar, şiddet ve ihmal gibi haram unsurların varlığına göre değişir."},
{"id":"kurbanbaskayer","yol":["Kurban ve av","Kurban"],"baslik":"Kurbanı başka şehirde veya ülkede kestirmek","ar":"نقل الأضحية",
 "hanefi":"Kurbanın kendi bulunduğu yerde kesilmesi ve etinin yakınlara ve fakirlere dağıtılması efdaldir. Bununla birlikte daha muhtaç bölgelerdeki insanlara ulaştırmak için vekâlet yoluyla başka şehirde veya ülkede kestirmek caizdir. Bu durumda kurbanın kesim vakti, kurbanın kesildiği yere göre belirlenir; vekilin bayram günlerinde kestiğinden emin olmak gerekir.",
 "mez":{"maliki":["Mekruh","İhtiyaç daha fazla ise caiz görülür."],
        "safii":["Tercih edilen: aynı yer","Günümüz Şâfiî âlimlerinin çoğu ihtiyaçla caiz görür."],
        "hanbeli":["Caiz","İhtiyaç ve maslahat bulunursa caizdir."]},
 "sebep":"Kurbanın ibadet yönü (kesimin kendisi) ile sosyal yardım yönü (etin muhtaçlara ulaşması) arasında öncelik.",
 "delil":[["ayet","Hac 22:28","./#22-28","“…Onlardan yiyin, sıkıntı içindeki yoksulu da doyurun.”"]],
 "usul":"Malî ibadetlerde vekâlet caizdir; vakit, fiilin gerçekleştiği yere göre belirlenir."},
{"id":"hayvanbakim","yol":["Kurban ve av","Yiyecekler"],"baslik":"Evde hayvan beslemek (kedi, köpek, kuş)","ar":"اقتناء الحيوانات الأليفة",
 "hanefi":"Kedi, kuş gibi hayvanları beslemek caizdir; onlara iyi bakmak sevap, eziyet etmek ve aç bırakmak günahtır. Köpeği bekçilik, çobanlık ve av gibi ihtiyaçlar için beslemek caizdir; ihtiyaç olmaksızın süs için evde köpek beslemek mekruh görülmüştür. Hanefîlere göre köpeğin bedeni necis değildir, ağzının suyu (salyası) necistir; bu sebeple köpeğin yaladığı kap yıkanır ve namaz kılınan yerin temizliğine dikkat edilir.",
 "mez":{"maliki":["Köpek temiz","Mâlikîlere göre köpek tamamen temizdir; yalnız kabı taabbüden yedi kez yıkanır."],
        "safii":["Köpek necis","Köpeğin bütün bedeni necistir; değen yer yedi kez, biri toprakla yıkanır."],
        "hanbeli":["Köpek necis","Şâfiîlerle aynı görüştedir."]},
 "sebep":"Köpeğin yaladığı kabın yedi kez yıkanması hadisinin, necaseti mi yoksa taabbüdî bir emri mi gösterdiği.",
 "delil":[["hadis","Kediye eziyet eden kadın",hadis("دخلت امرأة النار في هرة ربطتها"),"Buhârî, Bed’ü’l-halk, 16; Müslim, Selâm, 151."],
          ["hadis","İhtiyaç dışı köpek",hadis("من اقتنى كلبا إلا كلب ماشية أو ضار نقص من عمله كل يوم قيراطان"),"Buhârî, Zebâih, 6; Müslim, Müsâkāt, 50."]],
 "usul":"Hanefîler necaseti yalnız salyaya hasreder; ihtiyaçla beslemeyi hadisin istisnasına dayandırır."},
{"id":"oruckaza","yol":["Oruç","Oruç"],"baslik":"Ramazan orucunu bozan kişinin o günü geçirmesi","ar":"الإمساك لمن أفطر",
 "hanefi":"Ramazan gününde orucunu herhangi bir sebeple bozan veya oruçlu olmadığı hâlde gün içinde oruç yükümlülüğü başlayan kişi (yolculuktan dönen, hayzı biten, ergenliğe giren, Müslüman olan), Ramazan’ın saygınlığı için akşama kadar yiyip içmeden durur (imsâk). Bu kişiler o günü sonra kaza eder; ergenliğe giren ve Müslüman olan ise kaza etmez. Hasta ve yolcu orucunu açıkça yemek yerine gizli tutmalıdır.",
 "mez":{"maliki":["İmsâk müstehap","Mazeret ortadan kalkanın imsâkı gerekmez."],
        "safii":["İmsâk gerekmez (mazeretli için)","Kasten bozan imsâk eder."],
        "hanbeli":["İmsâk vacip","Hanefîlere yakındır."]},
 "sebep":"Ramazan gününün saygınlığının (hürmet-i vakt) imsâkı gerektirip gerektirmediği.",
 "delil":[["hadis","Âşûrâ günü sabah yemek yiyenlere imsâk emri",hadis("من أكل فليصم بقية يومه"),"Buhârî, Savm, 69; Müslim, Sıyâm, 135."]],
 "usul":"Vaktin hürmeti, oruç sahih olmasa da imsâkı gerektirir; Âşûrâ hadisine kıyas."},
]
